param([string]$Root=(Split-Path $PSScriptRoot -Parent))
Import-Module "$Root\Modules\Database.psm1" -Force;$c=Get-Content "$Root\Config\AppConfig.json" -Raw|ConvertFrom-Json;Initialize-PlatformDatabase (Join-Path $Root $c.DatabasePath) "$Root\Database\Migrations" "$Root\Database\Seed" $c.SeedDatabase;$drop=Join-Path $Root $c.NotificationDropFolder;New-Item $drop -ItemType Directory -Force|Out-Null
foreach($n in DB "SELECT * FROM NotificationQueue WHERE Status='Queued'"){try{$path=Join-Path $drop ("Notification-$($n.Id)-$(Get-Date -Format yyyyMMddHHmmss).json");[pscustomobject]@{Subject=$n.Subject;Recipient=$n.Recipient;Payload=$n.Payload}|ConvertTo-Json -Depth 6|Set-Content $path;DB "UPDATE NotificationQueue SET Status='Sent',SentOn=@d,Attempts=Attempts+1 WHERE Id=@i" @{d=(Get-Date).ToString('s');i=$n.Id}|Out-Null}catch{DB "UPDATE NotificationQueue SET Status='Failed',Attempts=Attempts+1,LastError=@e WHERE Id=@i" @{e=$_.Exception.Message;i=$n.Id}|Out-Null}}
